const input=$json.body??$json;
const cls=input.seller_response_classification??{};
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao);
const counter=Number(cls.counteroffer_amount??input.counteroffer_amount);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const classification=String(cls.classification||input.classification||"").toLowerCase();
const validMao=Number.isFinite(mao)&&mao>0;
const validCounter=Number.isFinite(counter)&&counter>0;
const nearBand=validMao&&validCounter&&counter<=mao*1.10;
let decision="needs_review",strategy="human_review",reason="negotiation evidence requires review";
if(blockers.length){decision="blocked";strategy="blocked";reason="active blockers present";}
else if(!validMao){decision="needs_review";strategy="recalibrate";reason="dynamic MAO is missing or invalid";}
else if(classification==="accepted"){decision="acceptance_ready";strategy="prepare_contract";reason="seller accepted the offer";}
else if(classification==="counteroffer"&&validCounter&&counter<=mao){decision="counteroffer_within_mao";strategy="accept_or_contract";reason="counteroffer is within protected dynamic MAO";}
else if(classification==="counteroffer"&&nearBand){decision="counteroffer_near_mao";strategy="revised_offer_or_walkaway";reason="counteroffer is above MAO but within controlled negotiation band";}
else if(classification==="counteroffer"&&validCounter&&counter>mao){decision="counteroffer_above_mao";strategy="walkaway_or_recalibration";reason="counteroffer exceeds protected dynamic MAO";}
else if(classification==="rejected"){decision="rejected";strategy="reengagement";reason="seller rejected the offer";}
else if(classification==="question"||classification==="other_response"){decision="clarification_required";strategy="clarify";reason="seller response needs clarification";}
else if(classification==="no_response"){decision="timeout_followup";strategy="followup";reason="seller has not responded";}
const guardrail=decision==="counteroffer_above_mao"?"HARD_BLOCK_ABOVE_DYNAMIC_MAO":"PASS";
let status="negotiation_decision_ready",nextWorkflow="WF-293",humanReview=false;
if(decision==="blocked"){status="negotiation_blocked";nextWorkflow="WF-126";humanReview=true;}
else if(decision==="needs_review"){status="negotiation_review_required";nextWorkflow="WF-126";humanReview=true;}
else if(["counteroffer_near_mao","counteroffer_above_mao","rejected","clarification_required"].includes(decision)){humanReview=true;nextWorkflow=decision==="rejected"?"WF-294":"WF-293";}
else if(decision==="timeout_followup"){nextWorkflow="WF-290";}
return [{json:{...input,workflow:"WF-292",workflow_name:"Seller Response → Negotiation Decision & Dynamic MAO Evaluation Controller",status,negotiation_decision:{classification,counteroffer_amount:validCounter?counter:null,dynamic_mao:validMao?mao:null,decision,strategy,reason,near_mao:nearBand,guardrail},next_workflow:nextWorkflow,human_review_required:humanReview,audit:{event_type:"negotiation_decision_dynamic_mao",idempotency_key:input.idempotency_key||`wf-292:${input.deal_id||"unknown"}:${input.dispatch_id||"none"}:${input.version||1}`}}}];
